(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const canvas = $('world-map');
  const ctx = canvas.getContext('2d');
  const mapFrame = $('map-frame');
  const STORE_KEY = 'worldcraft-save-v1';
  const seasons = ['SPRING', 'SUMMER', 'AUTUMN', 'WINTER'];
  const unitTypes = [
    { id: 'infantry', name: 'Infantry brigade', icon: '♟', cost: 0.8, power: 2, description: 'Versatile ground presence', qty: 1000 },
    { id: 'armor', name: 'Tank battalion', icon: '▰', cost: 2.4, power: 7, description: 'Armored ground formation', qty: 48 },
    { id: 'air', name: 'Fighter jet wing', icon: '✈', cost: 3.2, power: 8, description: 'Rapid-response air support', qty: 24 },
    { id: 'artillery', name: 'Artillery group', icon: '◉', cost: 1.6, power: 5, description: 'Long-range support unit', qty: 36 }
  ];
  let features = [];
  let countries = [];
  let hovered = null;
  let selected = null;
  let player = null;
  let state = null;
  let scale = 1;
  let offset = { x: 0, y: 0 };
  let drag = null;
  let feedIndex = 0;
  let saveTimer;
  let toastTimer;
  const flagEmoji = (iso) => !iso || iso.length !== 2 ? '🏳️' : [...iso.toUpperCase()].map(c => String.fromCodePoint(c.charCodeAt(0) + 127397)).join('');
  const number = (n) => new Intl.NumberFormat('en-US').format(Math.round(n));
  const money = (n) => '$' + (n >= 1000 ? (n / 1000).toFixed(1) + 'T' : n.toFixed(1) + 'B');
  const short = (n) => n >= 1e9 ? (n / 1e9).toFixed(1) + 'B' : n >= 1e6 ? (n / 1e6).toFixed(1) + 'M' : number(n);
  const cleanName = (name) => ({ 'United Republic of Tanzania': 'Tanzania', 'Democratic Republic of the Congo': 'DR Congo', 'Republic of the Congo': 'Congo' }[name] || name);
  const blankState = () => ({ playerIso: 'US', treasury: 200, turn: 1, units: {}, relations: {}, readiness: {}, claims: {}, owners: {}, feed: ['Your government has received an opening treasury of $200 billion.'], selectedIso: 'CA' });
  function loadState() {
    try {
      const saved = JSON.parse(localStorage.getItem(STORE_KEY));
      if (saved && saved.playerIso && Number.isFinite(saved.treasury)) return { ...blankState(), ...saved };
    } catch (e) { console.warn('Could not load save:', e); }
    return blankState();
  }
  function persist() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => { try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (e) { console.warn('Save unavailable:', e); } }, 80);
  }
  function coordsOf(feature) {
    const g = feature.geometry;
    if (!g) return [];
    return g.type === 'Polygon' ? [g.coordinates] : g.type === 'MultiPolygon' ? g.coordinates : [];
  }
  function estimateArea(feature) {
    const known = { US: 9834000, CA: 9985000, CN: 9597000, IN: 3287000, RU: 17098200, BR: 8516000, AU: 7692000 };
    if (known[feature.properties.iso]) return known[feature.properties.iso];
    let area = 0;
    const R = 6371;
    for (const polygon of coordsOf(feature)) for (let r = 0; r < polygon.length; r++) {
      const ring = polygon[r]; let sum = 0;
      for (let i = 0; i < ring.length; i++) {
        const a = ring[i], b = ring[(i + 1) % ring.length];
        sum += (b[0] - a[0]) * Math.PI / 180 * (2 + Math.sin(a[1] * Math.PI / 180) + Math.sin(b[1] * Math.PI / 180));
      }
      area += (r === 0 ? 1 : -1) * Math.abs(sum * R * R / 2);
    }
    return Math.max(100, Math.round(area));
  }
  function prepareCountries(geo) {
    features = (geo.features || []).filter(f => f.properties && f.geometry);
    const gdpMax = Math.max(...features.map(f => +f.properties.gdp || 0));
    const popMax = Math.max(...features.map(f => +f.properties.pop || 0));
    countries = features.map(f => {
      const p = f.properties;
      const gdp = Math.max(1, +p.gdp || 1), pop = Math.max(1, +p.pop || 1);
      const power = Math.round((0.62 * Math.sqrt(gdp / gdpMax) + 0.38 * Math.sqrt(pop / popMax)) * 100);
      return { feature: f, iso: p.iso || p.name.slice(0, 2).toUpperCase(), name: cleanName(p.name), continent: p.continent || 'World', pop, gdp, power, area: estimateArea(f) };
    }).sort((a, b) => a.name.localeCompare(b.name));
    const ranking = [...countries].sort((a, b) => b.power - a.power);
    countries.forEach(c => c.rank = ranking.indexOf(c) + 1);
    $('country-count').textContent = countries.length;
    player = countries.find(c => c.iso === state.playerIso) || countries.find(c => c.iso === 'US') || countries[0];
    state.playerIso = player.iso;
    selected = countries.find(c => c.iso === state.selectedIso) || countries.find(c => c.iso !== player.iso) || player;
    if (selected.iso === player.iso && countries.length > 1) selected = countries.find(c => c.iso !== player.iso);
    state.selectedIso = selected.iso;
  }
  const fmtArea = (area) => area >= 1e6 ? (area / 1e6).toFixed(2) + 'M' : number(area);
  function projection(lon, lat) {
    const w = canvas.width, h = canvas.height;
    return [(lon + 180) / 360 * w, (85 - lat) / 170 * h];
  }
  function pathFor(feature) {
    const path = new Path2D();
    for (const polygon of coordsOf(feature)) for (const ring of polygon) {
      if (!ring.length) continue;
      const first = projection(ring[0][0], ring[0][1]); path.moveTo(first[0], first[1]);
      for (let i = 1; i < ring.length; i++) { const p = projection(ring[i][0], ring[i][1]); path.lineTo(p[0], p[1]); }
      path.closePath();
    }
    return path;
  }
  function resizeCanvas() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
    drawMap();
  }
  function relation(iso) { return state.relations[iso] || 'neutral'; }
  function drawMap() {
    if (!ctx || !canvas.width || !canvas.height) return;
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    const ocean = ctx.createLinearGradient(0, 0, w, h);
    ocean.addColorStop(0, '#eaf2ed'); ocean.addColorStop(1, '#dfeae3');
    ctx.fillStyle = ocean; ctx.fillRect(0, 0, w, h);
    ctx.save();
    ctx.translate(w / 2 + offset.x, h / 2 + offset.y);
    ctx.scale(scale, scale); ctx.translate(-w / 2, -h / 2);
    ctx.strokeStyle = 'rgba(86,123,98,.12)'; ctx.lineWidth = 1 / scale;
    for (let lon = -150; lon <= 180; lon += 30) { const x = (lon + 180) / 360 * w; ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
    for (let lat = -60; lat <= 60; lat += 30) { const y = (85 - lat) / 170 * h; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
    for (const c of countries) {
      const path = c.path || (c.path = pathFor(c.feature));
      const status = relation(c.iso);
      ctx.fillStyle = state.owners[c.iso] === player.iso ? '#9ecb86' : c.iso === player.iso ? '#92bd72' : status === 'war' ? '#e5a19a' : status === 'ally' ? '#a7cbb0' : '#f7f8f2';
      ctx.fill(path, 'evenodd');
      ctx.strokeStyle = c.iso === selected?.iso ? '#b77f36' : c.iso === player.iso ? '#246849' : '#b9c9bb';
      ctx.lineWidth = (c.iso === selected?.iso ? 1.45 : .72) / scale;
      ctx.stroke(path);
    }
    ctx.restore();
    if (hovered) canvas.style.cursor = 'pointer'; else canvas.style.cursor = drag ? 'grabbing' : 'grab';
  }

function resizeCanvas() {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.max(1, Math.round(rect.width * dpr));
  canvas.height = Math.max(1, Math.round(rect.height * dpr));
  for (const c of countries) delete c.path;
  drawMap();
}
